def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        return "錯誤：除數不能為零！"
    return x / y

def main():
    print("--- 簡易 Python 計算機 ---")
    print("請選擇運算類型：")
    print("1. 加法 (+)")
    print("2. 減法 (-)")
    print("3. 乘法 (*)")
    print("4. 除法 (/)")

    choice = input("輸入選擇 (1/2/3/4): ")

    if choice in ('1', '2', '3', '4'):
        try:
            num1 = float(input("輸入第一個數字: "))
            num2 = float(input("輸入第二個數字: "))
        except ValueError:
            print("錯誤：請輸入有效的數字。")
            return

        if choice == '1':
            print(f"結果: {num1} + {num2} = {add(num1, num2)}")
        elif choice == '2':
            print(f"結果: {num1} - {num2} = {subtract(num1, num2)}")
        elif choice == '3':
            print(f"結果: {num1} * {num2} = {multiply(num1, num2)}")
        elif choice == '4':
            result = divide(num1, num2)
            if isinstance(result, str):
                print(result)
            else:
                print(f"結果: {num1} / {num2} = {result}")
    else:
        print("無效的選擇")

if __name__ == "__main__":
    main()

import os
from dataclasses import dataclass, field
from typing import List, Dict, Any

@dataclass
class AuditResult:
    is_passed: bool
    errors: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)

    def __str__(self):
        status = "✅ PASSED" if self.is_passed else "❌ FAILED"
        res = f"[{status}]\n"
        if self.errors:
            res += f"  Errors: {len(self.errors)} found\n"
            for e in self.errors:
                res += f"    - {e}\n"
        if self.warnings:
            res += f"  Warnings: {len(self.warnings)} found\n"
            for w in self.warnings:
                res += f"    - {w}\n"
        return res

class Auditor:
    """
    實作 7 項 QA 檢查標準的稽核引擎
    """
    def audit(self, data: Dict[str, Any], image_dir: str) -> AuditResult:
        errors = []
        warnings = []

        # 1. 圖片數量 (3~5 張)
        if not os.path.exists(image_dir):
            errors.append(f"圖片資料夾不存在: {image_dir}")
        else:
            img_files = [f for f in os.listdir(image_dir) if f.lower().endswith(('.png', '.jpg', '.jpeg'))]
            img_count = len(img_files)
            if img_count < 3:
                errors.append(f"圖片數量不足 (目前 {img_count} 張，需 3~5 張)")
            elif img_count > 5:
                warnings.append(f"圖片數量過多 (目前 {img_count} 張，建議 3~5 張)")

        # 2. 正文長度 (900~1100 字)
        content = data.get("content", "")
        content_len = len(content)
        if content_len < 900:
            errors.append(f"正文長度不足 (目前 {content_len} 字，需 900~1100 字)")
        elif content_len > 1100:
            warnings.append(f"正文長度過長 (目前 {content_len} 字，建議 900~1100 字)")

        # 3. 摘要存在且 < 100 字
        summary = data.get("summary", "")
        if not summary:
            errors.append("摘要內容缺失")
        elif len(summary) >= 100:
            errors.append(f"摘要過長 (目前 {len(summary)} 字，需 < 100 字)")

        # 4. 至少 3 張照片 (與項目 1 重複，但這裡檢查邏輯一致性)
        # (已在項目 1 處理)

        # 5. 至少 2 張為「過程」類型照片
        # 假設資料中會提供照片類型的 metadata
        photo_metadata = data.get("photo_metadata", [])
        process_photos = [p for p in photo_metadata if p.get("type") == "process"]
        if len(process_photos) < 2:
            errors.append(f"缺乏「過程」類型的照片 (目前僅 {len(process_photos)} 張)")

        # 6. 圖說品質 (25~40 字)
        captions = data.get("captions", [])
        if captions:
            for i, cap in enumerate(captions):
                if len(cap) < 25 or len(cap) > 40:
                    warnings.append(f"第 {i+1} 張照片圖說長度不合適 ({len(cap)} 字)")
        else:
            warnings.append("未提供任何照片圖說")

        # 7. 預估檔案大小 (< 4MB)
        # 這裡模擬一個檢查，實際應計算檔案大小
        est_size_mb = data.get("estimated_size_mb", 0)
        if est_size_mb >= 4:
            errors.append(f"預估檔案大小過大 ({est_size_mb}MB, 需 < 4MB)")

        is_passed = len(errors) == 0
        return AuditResult(is_passed=is_passed, errors=errors, warnings=warnings)
